#!/usr/bin/env bash
#
# Combined batch from three supplied sources (July 2026):
#
#  1. The Black Panther, Vol. XII No. 3 (August 10, 1974) — archived, and
#     mined: adds seven of the eleven Atmore-Holman Brothers not yet in
#     the database, Flores Forbes, Milton Eugene Lindsey (Chattanooga),
#     James Reynolds Mendoza (Milwaukee), and USS Midway courts-martial
#     sailors Daniel Long and Ozie Washington; adds the 1974 Fox
#     nightclub case to Robert Heard and (with the identification noted)
#     to Bruce Washington; fills Lincoln Heard aka "Makau Salik"; merges
#     the Wesley Robert Wells duplicate pair and appends his July 1,
#     1974 parole to the canonical record.
#  2. Oregon Historical Quarterly (Spring 2022), Margaret Butler oral
#     history — adds the three named arrestees of the 1993 National Day
#     of Action for Labor Law Reform sit-in at Portland NLRB offices:
#     Margaret Butler, Anne Sweet and Rick Ball.
#  3. International anarchist prisoners list 2025
#     (solidarity.international) — archived, and mined: every US
#     prisoner on the list is already in the database except Sofia
#     Johnson, added here; also merges the malik-fard-muhammad
#     spelling-variant duplicate pair found during the audit.
#
# Idempotent throughout: prisoner:add refuses duplicates, merges are
# guarded by slug existence, appends are marker-guarded, aka fills only
# when empty.
#
# Run from the repo root:  bash database/data/add-bp1974-ohq-af2025.sh

set -euo pipefail
cd "$(dirname "$0")/../.."

php artisan prisoners:merge-duplicates --only=wesley-robert-wells,malik-fard-muhammad --apply

