# --- Other Black Panther Aug 10, 1974 additions ---

php artisan prisoner:add '{"name":"Flores Forbes","first_name":"Flores","last_name":"Forbes","description":"Flores Forbes joined the Black Panther Party in San Diego as a teenager in 1968 and rose to assistant chief of staff, part of the security cadre around Huey P. Newton. In the first week of August 1974 he was arrested with Newton and six other Party members at the Fox nightclub in Oakland; Elaine Brown told the press that Forbes and Newton were beaten so severely while handcuffed that both needed hospital treatment, and that the announced charges — conspiracy to possess weapons, assaulting police officers and resisting arrest — followed a fight that never happened. In October 1977 he led the botched attack on the Richmond home of a witness against Newton in which fellow Panther Louis Johnson was killed and Forbes himself was wounded; after three years underground he surrendered in 1980, was convicted, and served about four and a half years in California prisons. After his release he earned a masters degree in urban planning, became a New York City planning executive and Columbia University administrator, and told his story in the memoir Will You Die with Me? My Life and the Black Panther Party (2006).","state":"California","race":"Black","gender":"Male","ideologies":["Black liberation"],"affiliation":["Black Panther Party"],"era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Arrested with Huey P. Newton and six other Black Panther Party members at the Fox nightclub, Oakland (August 1974) — announced charges of conspiracy to possess weapons, assaulting police officers and resisting arrest; beaten while handcuffed","convicted":"No — Elaine Brown reported the eight had not been formally charged; disposition not located"},{"charges":"Charges from the botched October 23, 1977 attack on the Richmond home of a witness against Huey P. Newton, in which fellow Panther Louis Johnson was killed and Forbes was wounded; he spent three years underground before surrendering in 1980","convicted":"Yes — served about four and a half years in California prisons; released mid-1980s"}]}' || true

php artisan prisoner:add '{"name":"Milton Eugene Lindsey","first_name":"Milton","middle_name":"Eugene","last_name":"Lindsey","description":"Milton Eugene Lindsey was a 23-year-old Black worker, husband and father of two in Chattanooga, Tennessee. Early on July 21, 1974, police officers Paul O'"'"'Rear and Buddy Hullander entered a Black nightclub on Main Street without cause, demanded identification, and arrested him; one officer told the other, per Lindsey, to stop in an alley and beat him, which they did with pistols, blackjacks, boots and spit, leaving multiple lacerations to his head and back. Officers then charged him with public drunkenness and assault and battery on police officers. At trial the defense produced a Polaroid of an officer with a swollen eye alleging Lindsey had assaulted him, but witnesses — including the officers themselves — testified Lindsey was not drunk, was never given a drunk test, and was not staggering; the judge dismissed the drunkenness charge yet still handed down suspended sentences on two counts of assault and battery and a 92-dollar fine. Reconstructed from The Black Panther, Vol. XII No. 3 (August 10, 1974).","state":"Tennessee","race":"Black","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Public drunkenness and assault and battery on police officers — after being falsely arrested at a Chattanooga nightclub on July 21, 1974 and beaten by the arresting officers en route to jail","arrest_date":"1974-07-21","convicted":"Partly — the drunkenness charge was dismissed; suspended sentences and a $92 fine on two assault-and-battery counts"}]}' || true

php artisan prisoner:add '{"name":"James Reynolds Mendoza","first_name":"James","middle_name":"Reynolds","last_name":"Mendoza","description":"James Reynolds Mendoza was a 19-year-old Chicano from Milwaukee'"'"'s Southside held in the city jail for the July 1974 shooting deaths of off-duty policemen Robert Riley and Thomas Matulis, who were killed — possibly with their own guns — after a drunken altercation involving Matulis'"'"'s own brother and his drinking companions. Mendoza was arrested at his cousin'"'"'s house fourteen hours later. A witness who saw the shooting from ten feet said she knew the assailant by name and that it was not Mendoza and that no Mexican-Americans were at the scene; twenty other witnesses also failed to link him to the shooting, while police ransacked homes and searched without warrants for evidence against him. The Black Panther reported his case as that of a brother unjustly held while the poor white and Chicano Southside was thrown into upheaval. Reconstructed from The Black Panther, Vol. XII No. 3 (August 10, 1974); the later disposition of his case has not been located.","state":"Wisconsin","race":"Chicano","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"institution_name":"Milwaukee City Jail","institution_city":"Milwaukee","institution_state":"Wisconsin","charges":"Held for the deaths of two off-duty Milwaukee policemen, July 1974, despite eyewitnesses exonerating him","convicted":"Unknown — hearing date not yet set at press time; disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Daniel Long","first_name":"Daniel","last_name":"Long","description":"Daniel Long, a 23-year-old fireman apprentice from St. Louis, Missouri, was one of eight USS Midway crewmen — of some 40 sent to special courts-martial — tried at Yokosuka, Japan beginning July 20, 1974 for missing the carrier'"'"'s June 14 sailing. Between 50 and 80 sailors had stayed ashore in a spontaneous protest against the racism, brutality, living conditions and unfair punishments under Captain Schulte'"'"'s command; the defense argued that extraordinary racism aboard drove the sailors to be absent without authority. Witnesses testified that their supervisor, Chief Rice, used blatant racial slurs against Third World sailors and kept a shitlist of people he was out to get. Judge Lt. Miles Eastwood sentenced Long to three months at hard labor, docked two-thirds of his pay for five months, and imposed a two-month jail term and $1,000 in fines. Reconstructed from The Black Panther, Vol. XII No. 3 (August 10, 1974).","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Absent without authority — special court-martial at Yokosuka for joining the June 14, 1974 USS Midway crew protest against shipboard racism and brutality","convicted":"Yes — three months at hard labor, two-thirds pay docked for five months, a two-month jail sentence and $1,000 in fines"}]}' || true

php artisan prisoner:add '{"name":"Ozie Washington","first_name":"Ozie","last_name":"Washington","description":"Ozie Washington was one of eight USS Midway crewmen — of some 40 sent to special courts-martial — tried at Yokosuka, Japan in July 1974 for missing the carrier'"'"'s June 14 sailing, after 50 to 80 sailors stayed ashore in a spontaneous protest against the racism, brutality and unfair punishments under Captain Schulte'"'"'s command. His court-martial proceeded even after brig personnel interfered with his lawyer-client relationship by confiscating literature his lawyer had given him; he testified about illegal searches for contraband and the low morale of a crew kept constantly in port. After five minutes of deliberation the judge sentenced him to 75 days at hard labor — on top of the 30 days he had already served awaiting trial — and a $118 fine. Reconstructed from The Black Panther, Vol. XII No. 3 (August 10, 1974).","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Absent without authority — special court-martial at Yokosuka for joining the June 14, 1974 USS Midway crew protest against shipboard racism and brutality; held 30 days awaiting trial","convicted":"Yes — 75 days at hard labor in addition to the 30 days served awaiting trial, and a $118 fine"}]}' || true

# --- Oregon Historical Quarterly (Spring 2022): 1993 Portland NLRB sit-in ---

php artisan prisoner:add '{"name":"Margaret Butler","first_name":"Margaret","last_name":"Butler","description":"Margaret Butler, born in Portland, Oregon in 1957, was a Communications Workers of America rank-and-file activist and organizer who co-founded the Portland Jobs with Justice coalition in April 1991 and served as its first paid organizer and then director from 1996 until her retirement in 2013, building it into one of the strongest labor-community coalitions in the country. During the 1993 National Day of Action for Labor Law Reform, Portland Jobs with Justice staged a sit-in at the National Labor Relations Board offices in the KOIN building; Butler was one of two who had signed up in advance for arrest, and one of nine arrested when police cleared the lobby. Reconstructed from her oral history in the Oregon Historical Quarterly, vol. 123 no. 1 (Spring 2022); the disposition of the arrests has not been located.","state":"Oregon","birthdate":"1957-01-01","gender":"Female","ideologies":["Labor movement"],"affiliation":["Jobs with Justice"],"era":"1990s","in_custody":false,"released":true,"cases":[{"charges":"Refusing to leave the lobby of the National Labor Relations Board offices in Portland'"'"'s KOIN building — one of nine arrested at the 1993 National Day of Action for Labor Law Reform sit-in","convicted":"Unknown — disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Anne Sweet","first_name":"Anne","last_name":"Sweet","description":"Anne Sweet was a Black labor activist in Portland, Oregon, a participant in the Summer Institute for Union Women and a friend of Portland Jobs with Justice organizer Margaret Butler. At the coalition'"'"'s 1993 National Day of Action for Labor Law Reform sit-in at the National Labor Relations Board offices in the KOIN building, she had insisted for weeks beforehand that she would not risk arrest — telling Butler, you do not know what they do to Black people in jail — but when police ordered the lobby cleared she refused to leave, and was one of the nine arrested. Reconstructed from Margaret Butler'"'"'s oral history in the Oregon Historical Quarterly, vol. 123 no. 1 (Spring 2022); the disposition of the arrests has not been located.","state":"Oregon","race":"Black","gender":"Female","ideologies":["Labor movement"],"affiliation":["Jobs with Justice"],"era":"1990s","in_custody":false,"released":true,"cases":[{"charges":"Refusing to leave the lobby of the National Labor Relations Board offices in Portland'"'"'s KOIN building — one of nine arrested at the 1993 National Day of Action for Labor Law Reform sit-in","convicted":"Unknown — disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Rick Ball","first_name":"Rick","last_name":"Ball","description":"Rick Ball was an organizer for Service Employees International Union Local 49 in Portland, Oregon. At the 1993 National Day of Action for Labor Law Reform — when about one hundred people joined Portland Jobs with Justice'"'"'s sit-in at the National Labor Relations Board offices in the KOIN building to demand real penalties for law-breaking employers and majority sign-up union recognition — Ball was one of only two, with Margaret Butler, who had signed up in advance to risk arrest, and one of the nine arrested when police cleared the lobby. Reconstructed from Margaret Butler'"'"'s oral history in the Oregon Historical Quarterly, vol. 123 no. 1 (Spring 2022); the disposition of the arrests has not been located.","state":"Oregon","gender":"Male","ideologies":["Labor movement"],"affiliation":["SEIU"],"era":"1990s","in_custody":false,"released":true,"cases":[{"charges":"Refusing to leave the lobby of the National Labor Relations Board offices in Portland'"'"'s KOIN building — one of nine arrested at the 1993 National Day of Action for Labor Law Reform sit-in","convicted":"Unknown — disposition not located"}]}' || true

# --- International prisoners list 2025: the one missing US prisoner ---

php artisan prisoner:add '{"name":"Sofia Johnson","first_name":"Sofia","last_name":"Johnson","description":"Sofia Johnson, known in the movement as Candle, is an anarchist prisoner from Oregon (she/they) supported by the international June 11 solidarity network and listed on the International Anarchist Defence Fund prisoners list. She is serving a 90-month mandatory-minimum sentence under Oregon'"'"'s Measure 11 (ORS 137.700) after a plea over the armed robbery of a Beaverton 7-Eleven — which netted about 860 dollars and some cigars — together with charges from squatting a vacant veterinary clinic. Supporters describe her as a dedicated anarchist whose politics deepened in custody; she writes and receives mail at Coffee Creek Correctional Facility. Her scheduled release date is December 22, 2028.","state":"Oregon","gender":"Female","aka":"Candle","inmate_number":"SID #23976151","ideologies":["Anarchism"],"era":"2020s","in_custody":true,"released":false,"cases":[{"institution_name":"Coffee Creek Correctional Facility","institution_city":"Wilsonville","institution_state":"Oregon","charges":"First-degree robbery (armed robbery of a Beaverton 7-Eleven) and charges from squatting a vacant veterinary clinic","convicted":"Yes — plea; 90-month mandatory minimum under Oregon Measure 11 (ORS 137.700)","release_date":"2028-12-22"}]}' || true

# --- Guarded record edits ---

php artisan tinker --execute='
$find = fn (string $slug) => \App\Models\Prisoner::withoutGlobalScopes()->where("slug", $slug)->first();
$appendOnce = function ($p, string $marker, string $paragraph): void {
    if (! $p || str_contains((string) $p->description, $marker)) { return; }
    $p->description = trim((string) $p->description) . "\n\n" . $paragraph;
    $p->save();
    echo "DESC {$p->slug}\n";
};
$hasCase = function ($p, string $needle): bool {
    foreach ($p->cases as $c) {
        $ch = is_array($c->charges) ? implode(" ", $c->charges) : (string) $c->charges;
        if (stripos($ch, $needle) !== false) { return true; }
    }
    return false;
};

$p = $find("lincoln-heard");
if ($p && empty($p->aka)) { $p->aka = "Makau Salik"; $p->save(); echo "AKA lincoln-heard\n"; }

$p = $find("robert-heard");
if ($p && ! $hasCase($p, "Fox nightclub")) {
    $p->cases()->create([
        "charges" => "Arrested with Huey P. Newton and six other Black Panther Party members at the Fox nightclub, Oakland (August 1974) — announced charges of conspiracy to possess weapons, assaulting police officers and resisting arrest; a federal ex-felon weapons hold was placed on him and Newton",
        "convicted" => "No — Elaine Brown reported the eight had not been formally charged; disposition not located",
    ]);
    echo "CASE robert-heard 1974\n";
}

$p = $find("bruce-washington");
if ($p && ! $hasCase($p, "Fox nightclub")) {
    $p->cases()->create([
        "charges" => "Two misdemeanor counts — reported by The Black Panther (August 10, 1974) as the fourth Party member charged after the Fox nightclub arrests of Huey P. Newton and seven other Panthers, presumably the same Oakland Party member killed that October",
        "convicted" => "Unknown — he was shot dead on October 26, 1974, weeks after the charges",
    ]);
    echo "CASE bruce-washington 1974\n";
}
$appendOnce($p, "Fox nightclub", "The Black Panther of August 10, 1974 reported that a Bruce Washington — presumably the same Oakland Party member — was the fourth B.P.P. member charged, on two misdemeanor counts, in the wake of the Fox nightclub arrests of Huey P. Newton and seven other Panthers that month.");

$p = $find("wesley-robert-wells");
$appendOnce($p, "July 1, 1974", "On July 1, 1974, at age 65, Wells was released on parole from the California Medical Facility at Vacaville after 47 years of confinement in California prisons, under the care of the Delancey Street Foundation. In a three-part interview with The Black Panther — whose attorney friend Charles Garry called him the original Panther — he described being sent to the STRESS psychiatric unit after 44 years inside, the 15-month parole denial that followed a clean bill of health, and his vow to keep struggling for prisoner rights (The Black Panther, August 10, 1974).");

\Illuminate\Support\Facades\Cache::forget(\App\Http\Controllers\Api\PrisonerApiController::cacheKey());
echo "Done.\n";
'

php artisan archive:add-bp-aug-1974-and-2025-list

echo
echo "Done. Black Panther Aug 1974 + OHQ Butler + 2025 list applied."
